        return differentMachineConstraint;
    }

    public void setDifferentMachineConstraint(boolean differentMachineConstraint) {
        this.differentMachineConstraint = differentMachineConstraint;
    }

    public boolean isSubmit() {
        return eventType == SUBMIT;
    }

    @Override
    public String toString() {
        return "TaskEvent{" +
                "timestamp=" + timestamp +
                ", jobId=" + jobId +
                ", taskIndex=" + taskIndex +
                ", eventType=" + eventType +
                '}';
    }
