        // Count the number of SUBMIT events per session (stage)
        DataStream<Tuple2<Long, Long>> sessionCounts = submitEvents
                .keyBy(TaskEvent::getJobId)
                .window(EventTimeSessionWindows.withGap(Time.minutes(10)))
                .aggregate(new CountAggregator());

        // For job events, assign timestamps
        SingleOutputStreamOperator<JobEvent> jobEventsWithTimestamp = jobEventsStream
                .filter(e -> e != null)
                .assignTimestampsAndWatermarks(
                        WatermarkStrategy.<JobEvent>forBoundedOutOfOrderness(Duration.ofMinutes(1))
                                .withTimestampAssigner((event, timestamp) -> event.getTimestamp() / 1000)
                );

        // Filter only job finish events (FINISH, FAIL, KILL, EVICT, LOST)
        DataStream<JobEvent> finishedJobs = jobEventsWithTimestamp
                .filter(JobEvent::isFinished);

        // Connect session counts with finished jobs to emit only when job finishes
        DataStream<Tuple2<Long, Long>> result = sessionCounts
                .keyBy(t -> t.f0)
                .connect(finishedJobs.keyBy(JobEvent::getJobId))
                .process(new MaxSessionOutputFunction());

        // Write output as formatted string
        result.map(new MapFunction<Tuple2<Long, Long>, String>() {
            @Override
            public String map(Tuple2<Long, Long> value) throws Exception {
                return "(" + value.f0 + "," + value.f1 + ")";
            }
        }).writeAsText(outputPath, FileSystem.WriteMode.OVERWRITE).setParallelism(1);

        env.execute("LongestSessionPerJob");
    }

    /**
     * Aggregates task events in a session window by counting them
     */
    public static class CountAggregator implements AggregateFunction<TaskEvent, Long, Tuple2<Long, Long>> {
        private long jobId = 0;

        @Override
        public Long createAccumulator() {
            return 0L;
        }

        @Override
        public Long add(TaskEvent value, Long accumulator) {
            jobId = value.getJobId();
            return accumulator + 1;
        }

        @Override
        public Tuple2<Long, Long> getResult(Long accumulator) {
            return Tuple2.of(jobId, accumulator);
        }

        @Override
        public Long merge(Long a, Long b) {
            return a + b;
        }
    }

    /**
     * Joins session counts with job finish events
     * Keeps track of maximum session count per job
     * Emits result when job finishes
     */
    public static class MaxSessionOutputFunction
            extends KeyedCoProcessFunction<Long, Tuple2<Long, Long>, JobEvent, Tuple2<Long, Long>> {

        // Stores the maximum session count for each job
        private ValueState<Long> maxSessionCount;
        // Stores whether the job has finished
        private ValueState<Boolean> jobFinished;
        // Stores whether we have emitted result
        private ValueState<Boolean> resultEmitted;

        @Override
        public void open(Configuration parameters) throws Exception {
            maxSessionCount = getRuntimeContext().getState(
                    new ValueStateDescriptor<>("maxSessionCount", Types.LONG));
            jobFinished = getRuntimeContext().getState(
                    new ValueStateDescriptor<>("jobFinished", Types.BOOLEAN));
            resultEmitted = getRuntimeContext().getState(
                    new ValueStateDescriptor<>("resultEmitted", Types.BOOLEAN));
        }

        @Override
        public void processElement1(Tuple2<Long, Long> sessionCount, Context ctx, Collector<Tuple2<Long, Long>> out) throws Exception {
            // Update max session count
            Long currentMax = maxSessionCount.value();
            if (currentMax == null || sessionCount.f1 > currentMax) {
                maxSessionCount.update(sessionCount.f1);
            }

            // If job has already finished, emit result
            Boolean finished = jobFinished.value();
            Boolean emitted = resultEmitted.value();
            if (finished != null && finished && (emitted == null || !emitted)) {
                Long max = maxSessionCount.value();
                if (max != null) {
                    out.collect(Tuple2.of(ctx.getCurrentKey(), max));
                    resultEmitted.update(true);
                }
            }
        }

        @Override
        public void processElement2(JobEvent jobEvent, Context ctx, Collector<Tuple2<Long, Long>> out) throws Exception {
            // Mark job as finished
            jobFinished.update(true);

            // If we have session counts and haven't emitted yet, emit result
            Boolean emitted = resultEmitted.value();
            Long max = maxSessionCount.value();
            if (max != null && (emitted == null || !emitted)) {
                out.collect(Tuple2.of(ctx.getCurrentKey(), max));
                resultEmitted.update(true);
            }
        }
    }

    /**
     * Source function for reading task events from a gzipped CSV file
     */
    public static class TaskEventSource implements SourceFunction<TaskEvent> {
        private final String filePath;
        private volatile boolean isRunning = true;

        public TaskEventSource(String filePath) {
            this.filePath = filePath;
        }

        @Override
        public void run(SourceContext<TaskEvent> ctx) throws Exception {
            try (BufferedReader reader = new BufferedReader(
                    new InputStreamReader(
                            new GZIPInputStream(new FileInputStream(filePath))))) {
                String line;
                while (isRunning && (line = reader.readLine()) != null) {
                    TaskEvent event = TaskEvent.fromString(line);
                    if (event != null) {
                        ctx.collect(event);
                    }
                }
            }
        }

        @Override
        public void cancel() {
            isRunning = false;
        }
    }

    /**
     * Source function for reading job events from a gzipped CSV file
     */
    public static class JobEventSource implements SourceFunction<JobEvent> {
